import { describe, expect, it } from 'vitest';
import { RateLimiter } from '../src/lib/limiter';
import { setup } from './helpers';

describe('POST /webhooks rate limiting', () => {
  it('answers 429 with a Retry-After header when a tenant exceeds the limit', async () => {
    const { postWebhook } = setup({ rateLimitMaxRequests: 2, rateLimitWindowMs: 60000 });

    expect((await postWebhook('tenant-a', { type: 'invoice.paid' })).status).toBe(202);
    expect((await postWebhook('tenant-a', { type: 'invoice.paid' })).status).toBe(202);

    const limited = await postWebhook('tenant-a', { type: 'invoice.paid' });
    expect(limited.status).toBe(429);
    const retryAfter = limited.headers.get('Retry-After');
    expect(retryAfter).not.toBeNull();
    expect(Number(retryAfter)).toBeGreaterThanOrEqual(1);
    expect(await limited.json()).toMatchObject({ error: expect.stringMatching(/rate limit/i) });
  });

  it('does not rate-limit other tenants', async () => {
    const { postWebhook } = setup({ rateLimitMaxRequests: 1, rateLimitWindowMs: 60000 });

    expect((await postWebhook('tenant-a', { type: 'x' })).status).toBe(202);
    expect((await postWebhook('tenant-a', { type: 'x' })).status).toBe(429);
    expect((await postWebhook('tenant-b', { type: 'x' })).status).toBe(202);
  });

  it('reads the limit from config rather than a constant', async () => {
    const { postWebhook } = setup({ rateLimitMaxRequests: 3, rateLimitWindowMs: 60000 });

    expect((await postWebhook('tenant-a', { type: 'x' })).status).toBe(202);
    expect((await postWebhook('tenant-a', { type: 'x' })).status).toBe(202);
    // A hardcoded limit of 1 or 2 would already have rejected this request.
    expect((await postWebhook('tenant-a', { type: 'x' })).status).toBe(202);
    expect((await postWebhook('tenant-a', { type: 'x' })).status).toBe(429);
  });

  it('slides the window so old hits stop counting', () => {
    const limiter = new RateLimiter();
    expect(limiter.check('tenant-a', 1, 1000, 0).allowed).toBe(true);
    expect(limiter.check('tenant-a', 1, 1000, 500).allowed).toBe(false);
    expect(limiter.check('tenant-a', 1, 1000, 1001).allowed).toBe(true);
  });
});

